-- 자동 생성 파일입니다. 고치지 말고 pnpm db:seed:generate로 다시 만듭니다.
begin;
set constraints all deferred;
insert into public.pantheons (slug, name, name_en, region, earliest_source, era_label, era_year, summary, description, cover_exhibit_id)
select slug, name, name_en, region, earliest_source, era_label, era_year, summary, description, cover_exhibit_id from jsonb_populate_recordset(null::public.pantheons, $seed$[{"slug":"egyptian","name":"이집트 신화","name_en":"Egyptian","region":"나일강 유역","earliest_source":"피라미드 텍스트","era_label":"기원전 24세기경","era_year":-2400,"summary":"죽음 이후의 삶과 심판, 태양의 순환을 중심으로 삼천 년 넘게 이어진 신화입니다.","description":["이집트 신화는 나일강의 범람과 태양의 운행처럼 되풀이되는 자연의 질서를 신들의 이야기로 풀어냈습니다.","왕의 무덤 벽에 새긴 피라미드 텍스트에서 시작해 관 텍스트, 사자의 서로 이어지며 죽은 이가 저승을 지나 심판을 받는 과정이 자세히 기록되었습니다."],"cover_exhibit_id":"weighing-heart"},{"slug":"mesopotamian","name":"메소포타미아 신화","name_en":"Mesopotamian","region":"티그리스·유프라테스강 유역","earliest_source":"수메르어 길가메시 시가","era_label":"기원전 21세기경","era_year":-2100,"summary":"점토판에 쐐기문자로 새긴, 인류가 남긴 가장 오래된 영웅 서사가 있는 신화입니다.","description":["수메르, 아카드, 바빌로니아, 아시리아로 이어진 도시 문명들은 신들을 도시의 수호자로 섬겼습니다.","죽음을 피하려 길을 떠난 길가메시의 이야기와 혼돈의 바다를 무찌르고 세계를 세운 마르두크의 창조 서사시 「에누마 엘리시」가 대표적입니다."],"cover_exhibit_id":"ishtar-gate-lion"},{"slug":"hindu","name":"인도 신화","name_en":"Hindu","region":"인도 아대륙","earliest_source":"리그베다","era_label":"기원전 15세기경","era_year":-1500,"summary":"창조와 유지, 파괴가 끝없이 되풀이되는 우주관 위에 수많은 신과 화신이 등장합니다.","description":["베다의 찬가에서 시작한 인도 신화는 「마하바라타」, 「라마야나」 같은 서사시와 푸라나 문헌으로 넓어졌습니다.","세계를 유지하는 비슈누와 파괴와 재생의 신 시바, 지혜와 시작의 신 가네샤처럼 지금도 널리 숭배되는 신들이 많습니다."],"cover_exhibit_id":"shiva-nataraja"},{"slug":"greek","name":"그리스 신화","name_en":"Greek","region":"에게해 연안","earliest_source":"호메로스 「일리아스」·「오디세이아」","era_label":"기원전 8세기경","era_year":-800,"summary":"올림포스의 열두 신과 영웅들의 이야기로, 서양 예술과 문학의 뿌리가 된 신화입니다.","description":["그리스 신화의 신들은 사람처럼 사랑하고 질투하며 다툽니다. 호메로스와 헤시오도스의 서사시가 그 이야기를 처음 글로 남겼습니다.","로마는 그리스의 신들을 자기 신들과 동일시해 받아들였고, 로마 시대에 만든 대리석 모작 덕분에 사라진 그리스 원작의 모습을 지금도 볼 수 있습니다."],"cover_exhibit_id":"artemision-bronze"},{"slug":"japanese","name":"일본 신화","name_en":"Japanese","region":"일본 열도","earliest_source":"「고사기」","era_label":"712년","era_year":712,"summary":"천지가 열리고 섬들이 태어나는 이야기에서 시작해 태양신의 후손으로 이어지는 신화입니다.","description":["712년에 엮은 「고사기」와 720년의 「일본서기」에 이자나기와 이자나미의 국토 창조, 아마테라스와 스사노오의 이야기가 실려 있습니다.","에도 시대와 메이지 시대의 우키요에 화가들은 이 장면들을 목판화로 즐겨 그렸습니다."],"cover_exhibit_id":"amaterasu-iwato"},{"slug":"norse","name":"북유럽 신화","name_en":"Norse","region":"스칸디나비아·아이슬란드","earliest_source":"「산문 에다」·「시 에다」","era_label":"13세기","era_year":1220,"summary":"거인과 싸우는 신들, 그리고 피할 수 없는 종말 라그나로크로 끝나는 신화입니다.","description":["북유럽 신화는 오랫동안 입으로 전해지다가 13세기 아이슬란드에서 스노리 스튀르류손의 「산문 에다」와 「시 에다」로 기록되었습니다.","19세기 낭만주의 시대에 스칸디나비아 화가들이 오딘과 토르를 다시 그리면서 오늘날 우리가 떠올리는 북유럽 신들의 모습이 만들어졌습니다."],"cover_exhibit_id":"thor-jotnar"},{"slug":"chinese","name":"중국 신화","name_en":"Chinese","region":"황허·창장 유역","earliest_source":"「산해경」·「초사」","era_label":"기원전 4세기경","era_year":-350,"summary":"하늘과 땅을 가른 거인 반고, 사람을 빚은 여와, 불사의 복숭아를 기르는 서왕모의 이야기가 여러 책에 흩어져 전하는 신화입니다.","description":["중국 신화는 한 권의 경전이 아니라 「산해경」, 「초사」, 「회남자」 같은 여러 책에 조각조각 흩어져 전합니다.","천지를 연 반고 이야기는 3세기 삼국 시대 오나라의 기록에 처음 보이는 등, 오래된 이야기와 후대에 덧붙은 이야기가 섞여 있습니다. 많은 신이 도교 신앙 속에서 오늘날까지 섬겨집니다."],"cover_exhibit_id":"fuxi-nuwa"},{"slug":"celtic","name":"켈트 신화","name_en":"Celtic","region":"아일랜드·브리튼·갈리아","earliest_source":"「둔 카우의 서」 (아일랜드 필사본)","era_label":"12세기","era_year":1100,"summary":"사슴뿔을 단 신, 까마귀로 날아다니는 전쟁의 여신, 아일랜드의 영웅 쿠 훌린이 등장하는 서유럽 켈트족의 신화입니다.","description":["갈리아 등 대륙 켈트족의 신화는 로마에 정복된 뒤 대부분 사라지고, 유물과 로마인의 기록으로만 일부 전합니다.","오늘날 알려진 이야기는 대부분 중세 아일랜드와 웨일스의 수도원에서 기록한 필사본에서 나왔습니다. 12세기 초에 만든 「둔 카우의 서」에는 쿠 훌린이 활약하는 얼스터 이야기가 실려 있습니다."],"cover_exhibit_id":"cernunnos-gundestrup"},{"slug":"aztec","name":"아즈텍 신화","name_en":"Aztec","region":"멕시코 중앙 고원","earliest_source":"그림 문서(코덱스)","era_label":"15~16세기","era_year":1500,"summary":"네 번 무너진 세상 뒤의 다섯 번째 태양 아래에서, 깃털 달린 뱀과 연기 나는 거울의 신이 맞서는 신화입니다.","description":["아즈텍 사람들은 세상이 이미 네 번 멸망했고 지금은 다섯 번째 태양의 시대라고 믿었습니다. 테스카틀리포카, 케찰코아틀, 틀랄록이 앞선 시대의 태양이었다고 전합니다.","신들의 모습은 그림 문서인 코덱스에 남아 있습니다. 스페인 정복 이전에 만든 「보르자 코덱스」와 정복 무렵의 「보르보니쿠스 코덱스」가 대표적입니다."],"cover_exhibit_id":"tezcatlipoca-borgia"}]$seed$::jsonb)
on conflict (slug) do nothing;
insert into public.figures (slug, pantheon_slug, name, name_en, epithet, domains, summary, description, sort_order)
select slug, pantheon_slug, name, name_en, epithet, domains, summary, description, sort_order from jsonb_populate_recordset(null::public.figures, $seed$[{"slug":"zeus","pantheon_slug":"greek","name":"제우스","name_en":"Zeus","epithet":"하늘과 번개의 신","domains":["하늘","번개","법과 질서"],"summary":"아버지 크로노스를 몰아내고 올림포스의 신들을 다스리게 된 신들의 왕입니다.","description":["제우스는 형제들과 함께 티탄족과 싸워 이긴 뒤 하늘을 맡았고, 포세이돈은 바다를, 하데스는 저승을 맡았습니다.","번개를 무기로 쓰며 손님과 맹세를 지키는 신으로도 섬겨졌습니다. 로마에서는 유피테르와 동일시되었습니다."],"sort_order":1},{"slug":"athena","pantheon_slug":"greek","name":"아테나","name_en":"Athena","epithet":"지혜와 전략의 여신","domains":["지혜","전쟁의 전략","공예"],"summary":"제우스의 머리에서 완전 무장한 채 태어났다고 전하는 아테네의 수호 여신입니다.","description":["아테나는 무작정 싸우는 전쟁이 아니라 계획과 전략의 전쟁을 맡았고, 베 짜기와 같은 공예의 신이기도 했습니다.","아테네 사람들에게 올리브나무를 선물해 포세이돈을 이기고 도시의 수호신이 되었다는 이야기가 유명합니다."],"sort_order":2},{"slug":"apollo","pantheon_slug":"greek","name":"아폴론","name_en":"Apollo","epithet":"빛과 예언, 음악의 신","domains":["예언","음악","치유","궁술"],"summary":"델포이 신탁의 주인으로, 리라를 연주하는 젊은 신의 모습으로 자주 표현됩니다.","description":["아폴론은 제우스와 레토의 아들이자 아르테미스의 쌍둥이 형제입니다.","델포이에서 왕뱀 피톤을 물리치고 신탁소를 세웠다고 전하며, 사람들은 중요한 일을 앞두고 그곳에서 아폴론의 뜻을 물었습니다."],"sort_order":3},{"slug":"aphrodite","pantheon_slug":"greek","name":"아프로디테","name_en":"Aphrodite","epithet":"사랑과 아름다움의 여신","domains":["사랑","아름다움","욕망"],"summary":"바다 거품에서 태어났다고 전하는 사랑의 여신으로, 로마에서는 베누스라 불렸습니다.","description":["헤시오도스의 「신통기」는 아프로디테가 바다 거품에서 태어났다고 하고, 호메로스는 제우스와 디오네의 딸이라고 합니다.","트로이 전쟁의 발단이 된 ‘파리스의 심판’에서 가장 아름다운 여신으로 뽑혔습니다."],"sort_order":4},{"slug":"poseidon","pantheon_slug":"greek","name":"포세이돈","name_en":"Poseidon","epithet":"바다와 지진의 신","domains":["바다","지진","말"],"summary":"삼지창으로 바다를 다스리고 땅을 뒤흔드는 신입니다.","description":["포세이돈은 제우스의 형제로, 화가 나면 폭풍과 지진을 일으킨다고 여겨졌습니다.","「오디세이아」에서는 아들 폴리페모스의 눈을 멀게 한 오디세우스가 고향에 돌아가지 못하도록 오랫동안 방해합니다."],"sort_order":5},{"slug":"odin","pantheon_slug":"norse","name":"오딘","name_en":"Odin","epithet":"지혜와 죽음, 전쟁의 신","domains":["지혜","시","전쟁","죽음"],"summary":"지혜를 얻으려 한쪽 눈을 내놓은, 아스가르드의 주신입니다.","description":["오딘은 미미르의 샘물을 마시려고 한쪽 눈을 바쳤고, 룬 문자의 비밀을 얻으려 세계수 이그드라실에 아흐레 동안 매달렸다고 합니다.","여덟 다리를 가진 말 슬레이프니르를 타고 다니며, 라그나로크에서 늑대 펜리르에게 삼켜질 운명입니다."],"sort_order":1},{"slug":"thor","pantheon_slug":"norse","name":"토르","name_en":"Thor","epithet":"천둥의 신","domains":["천둥","힘","인간의 수호"],"summary":"망치 묠니르로 거인들과 싸우며 신과 사람의 세계를 지키는 신입니다.","description":["토르는 오딘의 아들로, 염소 두 마리가 끄는 수레를 타고 하늘을 달리면 천둥이 친다고 여겨졌습니다.","라그나로크에서 세계를 휘감은 뱀 요르문간드와 싸워 쓰러뜨리지만, 그 독에 쓰러진다고 전합니다."],"sort_order":2},{"slug":"freyja","pantheon_slug":"norse","name":"프레이야","name_en":"Freyja","epithet":"사랑과 풍요, 마법의 여신","domains":["사랑","풍요","세이드 마법"],"summary":"목걸이 브리싱가멘의 주인이자, 전사한 이들의 절반을 맞이하는 바니르 신족의 여신입니다.","description":["프레이야는 고양이가 끄는 수레를 탄다고 전하며, 전장에서 죽은 이들의 절반을 자신의 저택 폴크방으로 데려갑니다.","난쟁이들이 만든 목걸이 브리싱가멘을 로키가 훔치자 헤임달이 되찾아 돌려주었다는 이야기가 있습니다."],"sort_order":3},{"slug":"loki","pantheon_slug":"norse","name":"로키","name_en":"Loki","epithet":"꾀와 변신의 신","domains":["속임수","변신","혼란"],"summary":"신들을 돕기도, 곤경에 빠뜨리기도 하는 변신의 명수입니다.","description":["로키는 거인의 혈통이지만 아스가르드의 신들과 함께 지냈습니다. 펜리르, 요르문간드, 헬이 그의 자식입니다.","발드르의 죽음을 꾸민 대가로 결박당했다가 라그나로크에 풀려나 신들에게 맞선다고 전합니다."],"sort_order":4},{"slug":"osiris","pantheon_slug":"egyptian","name":"오시리스","name_en":"Osiris","epithet":"저승과 부활의 신","domains":["저승","부활","농경"],"summary":"동생 세트에게 죽임을 당했다가 되살아나 저승의 왕이 된 신입니다.","description":["오시리스는 세트에게 살해되어 몸이 흩어졌지만, 아내 이시스가 조각을 모아 되살렸다고 전합니다.","이후 저승을 다스리며 죽은 이들을 심판했고, 왕관과 갈고리 지팡이, 도리깨를 든 미라의 모습으로 표현됩니다."],"sort_order":1},{"slug":"isis","pantheon_slug":"egyptian","name":"이시스","name_en":"Isis","epithet":"마법과 모성의 여신","domains":["마법","모성","치유"],"summary":"죽은 남편 오시리스를 되살리고 아들 호루스를 지켜 낸 여신입니다.","description":["이시스는 강력한 마법으로 오시리스를 되살렸고, 늪지에 숨어 아들 호루스를 길렀습니다.","아기 호루스에게 젖을 먹이는 이시스의 모습은 이집트 전역에서 소상으로 만들어졌고, 그리스·로마 세계에서도 널리 숭배되었습니다."],"sort_order":2},{"slug":"anubis","pantheon_slug":"egyptian","name":"아누비스","name_en":"Anubis","epithet":"미라와 무덤의 신","domains":["장례","미라","저승 안내"],"summary":"자칼의 머리를 한 신으로, 죽은 이를 저승으로 이끌고 심장의 무게를 단다고 여겨졌습니다.","description":["아누비스는 미라를 만드는 의식을 지키는 신으로, 장례를 맡은 사제들은 그의 가면을 쓰고 의식을 치렀다고 합니다.","「사자의 서」의 심판 장면에서는 죽은 이의 심장을 진리의 깃털과 함께 저울에 올려 무게를 답니다."],"sort_order":3},{"slug":"gilgamesh","pantheon_slug":"mesopotamian","name":"길가메시","name_en":"Gilgamesh","epithet":"우루크의 왕","domains":["영웅","왕권","죽음과 영생"],"summary":"친구 엔키두를 잃고 영원한 삶을 찾아 떠난 우루크의 영웅 왕입니다.","description":["길가메시는 삼분의 이는 신, 삼분의 일은 사람이라고 전하는 우루크의 왕입니다. 실제 왕이었을 가능성도 있습니다.","「길가메시 서사시」에서 그는 엔키두와 함께 괴물 훔바바를 물리치지만, 엔키두가 죽자 죽음을 피하는 길을 찾아 나섭니다."],"sort_order":1},{"slug":"ishtar","pantheon_slug":"mesopotamian","name":"이슈타르","name_en":"Ishtar","epithet":"사랑과 전쟁의 여신","domains":["사랑","전쟁","금성"],"summary":"수메르에서는 인안나라고 불린, 사랑과 전쟁을 함께 다스리는 여신입니다.","description":["이슈타르는 저녁과 새벽의 금성으로 상징되었고, 사자는 그녀의 신성한 동물이었습니다.","저승으로 내려갔다가 돌아오는 「인안나의 저승 하강」 이야기가 유명합니다. 바빌론의 이슈타르 문에는 사자를 새긴 유약 벽돌이 늘어서 있었습니다."],"sort_order":2},{"slug":"marduk","pantheon_slug":"mesopotamian","name":"마르두크","name_en":"Marduk","epithet":"바빌론의 수호신","domains":["창조","왕권","정의"],"summary":"혼돈의 여신 티아마트를 무찌르고 그 몸으로 하늘과 땅을 만든 바빌론의 주신입니다.","description":["창조 서사시 「에누마 엘리시」에서 마르두크는 신들의 왕이 되는 조건으로 티아마트와 싸우겠다고 나섭니다.","바빌론이 강해지면서 마르두크는 메소포타미아의 가장 높은 신이 되었고, 용 모양의 짐승 무슈후슈가 그를 상징합니다."],"sort_order":3},{"slug":"vishnu","pantheon_slug":"hindu","name":"비슈누","name_en":"Vishnu","epithet":"세계를 유지하는 신","domains":["유지","보호","화신(아바타라)"],"summary":"세상의 질서가 무너질 때마다 화신으로 내려와 세계를 지키는 신입니다.","description":["비슈누는 라마와 크리슈나를 비롯한 여러 화신(아바타라)으로 세상에 나타난다고 여겨집니다.","우주가 쉬는 동안 뱀 아난타(셰샤) 위에 누워 잠들어 있다가, 배꼽에서 피어난 연꽃에서 창조의 신 브라흐마가 태어난다고 합니다."],"sort_order":1},{"slug":"shiva","pantheon_slug":"hindu","name":"시바","name_en":"Shiva","epithet":"파괴와 재생의 신","domains":["파괴","재생","고행","춤"],"summary":"낡은 우주를 허물어 새 우주가 태어나게 하는 신으로, 춤의 왕 나타라자로도 표현됩니다.","description":["시바는 히말라야에서 명상하는 고행자이면서, 아내 파르바티와 아들 가네샤, 스칸다를 둔 가장이기도 합니다.","불꽃 고리 안에서 춤추는 나타라자 상은 우주의 창조와 파괴가 이어지는 리듬을 나타냅니다."],"sort_order":2},{"slug":"ganesha","pantheon_slug":"hindu","name":"가네샤","name_en":"Ganesha","epithet":"지혜와 시작의 신","domains":["지혜","시작","장애 제거"],"summary":"코끼리 머리를 한 시바와 파르바티의 아들로, 새로운 일을 시작할 때 먼저 찾는 신입니다.","description":["가네샤가 코끼리 머리를 갖게 된 사연은 여러 가지로 전하는데, 시바가 아들인 줄 모르고 목을 벤 뒤 코끼리 머리를 붙여 주었다는 이야기가 널리 알려져 있습니다.","장애를 없애 주는 신으로 여겨져, 의식이나 새로운 일을 시작할 때 가장 먼저 기도를 받습니다."],"sort_order":3},{"slug":"izanagi-izanami","pantheon_slug":"japanese","name":"이자나기와 이자나미","name_en":"Izanagi & Izanami","epithet":"국토를 낳은 부부 신","domains":["창조","국토","삶과 죽음"],"summary":"하늘의 창으로 바다를 휘저어 첫 섬을 만들고 일본의 섬들과 신들을 낳은 부부 신입니다.","description":["두 신은 하늘에 걸린 다리에 서서 창으로 바다를 휘저었고, 창끝에서 떨어진 소금물이 굳어 첫 섬이 되었다고 합니다.","불의 신을 낳다가 죽은 이자나미를 찾아 이자나기는 저승 요미로 내려가지만, 끝내 데려오지 못하고 돌아옵니다."],"sort_order":1},{"slug":"amaterasu","pantheon_slug":"japanese","name":"아마테라스","name_en":"Amaterasu","epithet":"태양의 여신","domains":["태양","다카마가하라 통치"],"summary":"동굴에 숨어 세상을 어둠에 빠뜨렸다가 신들의 꾀로 다시 나온 태양의 여신입니다.","description":["아마테라스는 이자나기가 저승에서 돌아와 몸을 씻을 때 왼쪽 눈에서 태어났다고 「고사기」는 전합니다.","동생 스사노오의 난폭함에 화가 나 바위 동굴 아마노이와토에 숨자 세상이 어두워졌고, 신들은 동굴 앞에서 춤판을 벌여 그녀를 밖으로 이끌어 냈습니다."],"sort_order":2},{"slug":"susanoo","pantheon_slug":"japanese","name":"스사노오","name_en":"Susanoo","epithet":"폭풍과 바다의 신","domains":["폭풍","바다"],"summary":"하늘에서 쫓겨난 뒤 이즈모에서 머리 여덟 개 달린 큰 뱀 야마타노오로치를 물리친 신입니다.","description":["스사노오는 이자나기의 코에서 태어났다고 전합니다. 다카마가하라에서 난동을 부리다 쫓겨났습니다.","이즈모에서 야마타노오로치에게 술을 먹여 잠재운 뒤 베었고, 그 꼬리에서 나온 검 구사나기를 아마테라스에게 바쳤습니다."],"sort_order":3},{"slug":"raijin","pantheon_slug":"japanese","name":"라이진","name_en":"Raijin","epithet":"번개와 천둥의 신","domains":["천둥","번개","비"],"summary":"북을 둥글게 두르고 두드려 천둥을 울린다고 여겨진 신으로, 바람의 신 후진과 짝을 이룹니다.","description":["라이진은 오니와 비슷한 모습에 북을 고리처럼 둘러멘 모습으로 그려집니다.","바람의 신 후진과 함께 사찰의 문이나 병풍 그림에 자주 등장합니다."],"sort_order":4},{"slug":"hera","pantheon_slug":"greek","name":"헤라","name_en":"Hera","epithet":"신들의 여왕","domains":["결혼","가정","여성"],"summary":"제우스의 아내이자 누나로, 결혼과 가정을 지키는 올림포스의 여왕입니다.","description":["헤라는 크로노스와 레아의 딸로, 제우스와 결혼해 신들의 여왕이 되었습니다. 공작과 석류, 왕관과 홀이 헤라의 상징입니다.","제우스가 다른 여신과 인간에게서 얻은 자식들을 미워해 괴롭힌 이야기가 많은데, 영웅 헤라클레스가 대표적입니다. 로마에서는 유노와 동일시되었습니다."],"sort_order":6},{"slug":"artemis","pantheon_slug":"greek","name":"아르테미스","name_en":"Artemis","epithet":"사냥과 달의 여신","domains":["사냥","야생","달","소녀의 수호"],"summary":"아폴론의 쌍둥이 누이로, 활을 들고 숲과 산의 짐승을 다스리는 처녀 여신입니다.","description":["아르테미스는 제우스와 레토의 딸로, 델로스섬에서 아폴론과 함께 태어났습니다.","사냥꾼과 소녀들의 수호신이었으며, 목욕하는 자신을 엿본 사냥꾼 악타이온을 사슴으로 바꾸어 버린 이야기처럼 범할 수 없는 순결의 신으로 그려집니다. 후대에는 달의 여신으로도 여겨졌습니다."],"sort_order":7},{"slug":"hermes","pantheon_slug":"greek","name":"헤르메스","name_en":"Hermes","epithet":"신들의 전령","domains":["전령","여행","상업","도둑"],"summary":"날개 달린 신발을 신고 신들의 말을 전하며, 죽은 이의 영혼을 저승으로 이끄는 신입니다.","description":["헤르메스는 제우스와 마이아의 아들로, 태어난 날 아폴론의 소 떼를 훔치고 거북 등딱지로 리라를 만들어 아폴론에게 주었다고 합니다.","여행자와 상인, 도둑의 수호신이며, 뱀 두 마리가 감긴 지팡이 케리케이온을 듭니다. 로마에서는 메르쿠리우스라 불렸습니다."],"sort_order":8},{"slug":"hades","pantheon_slug":"greek","name":"하데스","name_en":"Hades","epithet":"저승의 왕","domains":["저승","죽은 이","땅속의 부"],"summary":"제우스·포세이돈과 세계를 나눠 저승을 맡은 신으로, 올림포스 열두 신에는 들지 않습니다.","description":["하데스는 크로노스와 레아의 아들로, 티탄족과의 싸움이 끝난 뒤 제비를 뽑아 저승을 맡았습니다. 이름은 ‘보이지 않는 자’라는 뜻으로 풀이됩니다.","데메테르의 딸 페르세포네를 데려가 아내로 삼았고, 그녀가 저승의 석류를 먹은 탓에 한 해의 일부를 저승에서 지내게 되면서 계절이 생겼다고 전합니다. 땅속의 부를 다스린다 하여 플루톤이라고도 불렸습니다."],"sort_order":9},{"slug":"baldr","pantheon_slug":"norse","name":"발드르","name_en":"Baldr","epithet":"빛과 순수의 신","domains":["빛","정의","아름다움"],"summary":"모든 것에게서 사랑받았지만 겨우살이에 맞아 죽은 오딘의 아들입니다.","description":["발드르는 오딘과 프리그의 아들로, 가장 아름답고 현명한 신이었습니다. 그가 죽는 꿈을 꾸자 프리그는 세상 모든 것에게 그를 해치지 않겠다는 맹세를 받았지만, 어리다고 여긴 겨우살이만은 빠뜨렸습니다.","로키가 이를 알아내 눈먼 신 회드에게 겨우살이를 던지게 했고, 발드르는 죽었습니다. 그의 죽음은 라그나로크로 이어지는 불행의 시작이 되며, 라그나로크 뒤 새 세상에서 되살아난다고 전합니다."],"sort_order":5},{"slug":"heimdall","pantheon_slug":"norse","name":"헤임달","name_en":"Heimdall","epithet":"신들의 파수꾼","domains":["경계","파수"],"summary":"무지개다리 비프로스트를 지키며, 라그나로크가 오면 뿔피리 걀라르호른을 불어 알리는 신입니다.","description":["헤임달은 아홉 어머니에게서 태어났다고 전하며, 새보다 잠을 적게 자고 풀과 양털이 자라는 소리까지 듣는다고 합니다.","아스가르드로 이어지는 비프로스트 곁에서 거인들을 지키다가, 라그나로크에는 걀라르호른을 불어 신들을 깨우고 로키와 싸워 함께 쓰러진다고 「산문 에다」는 전합니다."],"sort_order":6},{"slug":"ra","pantheon_slug":"egyptian","name":"라","name_en":"Ra","epithet":"태양신","domains":["태양","창조","왕권"],"summary":"태양의 배를 타고 낮에는 하늘을, 밤에는 저승을 건너는 이집트의 최고신입니다.","description":["라는 제5왕조 무렵부터 이집트의 최고신으로 섬겨졌고, 헬리오폴리스가 신앙의 중심이었습니다. 아침 해는 케프리, 저녁 해는 아툼으로 불리기도 했습니다.","밤마다 저승을 지나는 라의 배를 거대한 뱀 아포피스가 공격하지만, 라는 매번 이겨 다시 떠오른다고 여겨졌습니다. 매의 머리 위에 해 원반을 인 라-호라크티의 모습으로도 그려집니다."],"sort_order":4},{"slug":"horus","pantheon_slug":"egyptian","name":"호루스","name_en":"Horus","epithet":"하늘과 왕권의 신","domains":["하늘","왕권","수호"],"summary":"오시리스와 이시스의 아들로, 아버지를 죽인 세트와 싸워 이집트의 왕위를 되찾은 매의 신입니다.","description":["호루스는 매 또는 매의 머리를 한 사람으로 표현되며, 살아 있는 파라오는 호루스의 화신으로 여겨졌습니다.","세트와 싸우다 다친 눈은 토트가 고쳐 주었다고 하는데, 이 ‘호루스의 눈’은 온전함과 보호를 뜻하는 부적으로 널리 쓰였습니다. 에드푸 신전이 호루스를 모신 대표적인 신전입니다."],"sort_order":5},{"slug":"thoth","pantheon_slug":"egyptian","name":"토트","name_en":"Thoth","epithet":"지혜와 문자의 신","domains":["문자","지혜","기록","달"],"summary":"따오기 또는 개코원숭이의 모습으로 그려지는, 문자를 만든 지혜의 신입니다.","description":["토트는 신성문자를 만들고 신들의 서기 노릇을 했다고 여겨졌으며, 헤르모폴리스가 신앙의 중심이었습니다.","죽은 이의 심장을 다는 심판에서 결과를 기록하는 것도 토트의 일이었습니다. 그리스인들은 토트를 헤르메스와 동일시했습니다."],"sort_order":6},{"slug":"enki","pantheon_slug":"mesopotamian","name":"엔키","name_en":"Enki","epithet":"물과 지혜의 신","domains":["민물","지혜","마법","창조"],"summary":"수메르에서는 엔키, 아카드에서는 에아라 불린, 땅속 민물과 지혜를 다스리는 신입니다.","description":["엔키는 하늘의 신 안의 아들로, 땅 밑 민물의 바다 압수에 산다고 여겨졌습니다. 에리두가 신앙의 중심이었습니다.","사람을 만들고 문명의 기술을 전한 신으로 그려지며, 대홍수 이야기에서는 신들의 결정을 몰래 알려 한 사람이 배를 지어 살아남게 합니다."],"sort_order":4},{"slug":"tiamat","pantheon_slug":"mesopotamian","name":"티아마트","name_en":"Tiamat","epithet":"원초의 바다","domains":["바닷물","혼돈"],"summary":"민물의 신 압수와 함께 처음의 신들을 낳았고, 끝내 마르두크에게 쓰러진 바다의 여신입니다.","description":["창조 서사시 「에누마 엘리시」에서 티아마트는 바닷물을, 남편 압수는 민물을 나타내며, 둘의 물이 섞여 신들이 태어났다고 합니다.","압수가 젊은 신들에게 죽자 티아마트는 괴물들을 만들어 복수에 나섰지만 마르두크에게 쓰러졌고, 마르두크는 그 몸을 둘로 갈라 하늘과 땅을 만들었습니다."],"sort_order":5},{"slug":"brahma","pantheon_slug":"hindu","name":"브라흐마","name_en":"Brahma","epithet":"창조의 신","domains":["창조","베다","지혜"],"summary":"네 얼굴로 사방을 보는 창조의 신으로, 비슈누·시바와 함께 세 주신(트리무르티)을 이룹니다.","description":["브라흐마는 비슈누의 배꼽에서 피어난 연꽃에서 태어났다는 이야기와 스스로 태어났다는 이야기가 함께 전합니다. 아내는 학문과 예술의 여신 사라스바티입니다.","창조의 신이지만 오늘날 브라흐마만을 모시는 사원은 드뭅니다. 불교에서는 범천으로 받아들여졌습니다."],"sort_order":4},{"slug":"krishna","pantheon_slug":"hindu","name":"크리슈나","name_en":"Krishna","epithet":"비슈누의 여덟 번째 화신","domains":["사랑","보호","가르침"],"summary":"목동들 사이에서 자란 비슈누의 화신으로, 「바가바드 기타」에서 아르주나에게 가르침을 주는 신입니다.","description":["크리슈나는 ‘검은’ 또는 ‘검푸른’이라는 뜻으로, 그림에서는 흔히 푸른 피부에 피리를 든 모습으로 그려집니다. 어린 시절 마을 사람들을 폭우에서 지키려고 고바르다나산을 들어 올렸다는 이야기가 유명합니다.","「마하바라타」의 전쟁에서는 아르주나의 마부가 되어 의무와 헌신에 대해 가르치는데, 이 대화가 「바가바드 기타」입니다."],"sort_order":5},{"slug":"fujin","pantheon_slug":"japanese","name":"후진","name_en":"Fujin","epithet":"바람의 신","domains":["바람"],"summary":"바람이 든 자루를 메고 하늘을 달리는 신으로, 천둥의 신 라이진과 짝을 이룹니다.","description":["후진은 오니처럼 생긴 몸에 바람 자루를 두르고, 그 자루를 열어 바람을 일으킨다고 여겨졌습니다.","17세기 화가 다와라야 소타쓰가 금박 바탕에 후진과 라이진을 그린 「풍신뇌신도」 병풍은 일본의 국보입니다."],"sort_order":5},{"slug":"inari","pantheon_slug":"japanese","name":"이나리","name_en":"Inari","epithet":"벼와 풍요의 신","domains":["벼농사","풍요","장사의 번성"],"summary":"여우를 사자로 부리는 곡식의 신으로, 붉은 도리이가 늘어선 이나리 신사에서 모십니다.","description":["이나리라는 이름은 ‘벼가 자란다’는 말에서 왔다는 설이 있으며, 남신·여신 등 여러 모습으로 그려집니다. 교토의 후시미 이나리 신사가 대표적입니다.","여우는 이나리의 사자로 여겨져 신사 곳곳에 여우 석상이 놓입니다. 섣달그믐 밤 오지 이나리 신사 근처에 여우들이 모인다는 전설은 우타가와 히로시게의 판화로도 그려졌습니다."],"sort_order":6},{"slug":"pangu","pantheon_slug":"chinese","name":"반고","name_en":"Pangu","epithet":"천지를 연 거인","domains":["창조","하늘과 땅"],"summary":"혼돈의 알에서 깨어나 하늘과 땅을 갈라놓고, 죽은 뒤 몸이 세상 만물이 된 거인입니다.","description":["반고는 알처럼 뒤섞인 혼돈 속에서 태어나 하늘과 땅을 갈랐고, 하늘이 내려앉지 않도록 1만 8천 년 동안 떠받쳤다고 합니다.","그가 죽자 숨은 바람과 구름, 두 눈은 해와 달, 피는 강이 되었다고 전합니다. 이 이야기는 3세기 삼국 시대 오나라의 기록에 처음 보여, 다른 중국 신화보다 늦게 자리 잡았습니다."],"sort_order":1},{"slug":"nuwa","pantheon_slug":"chinese","name":"여와","name_en":"Nüwa","epithet":"사람을 빚은 여신","domains":["인류 창조","혼인","하늘을 기움"],"summary":"황토로 사람을 빚고, 무너진 하늘을 오색 돌로 기운 뱀 몸의 여신입니다.","description":["여와는 사람의 윗몸에 뱀의 몸을 한 모습으로 그려지며, 황토를 빚어 사람을 만들었다고 합니다. 복희와 남매 또는 부부로 짝지어지는 것은 한나라 무렵부터입니다.","「회남자」에 따르면 하늘을 받치던 기둥이 부러져 세상이 불과 물에 휩싸이자, 여와가 오색 돌을 녹여 하늘의 구멍을 메웠다고 합니다."],"sort_order":2},{"slug":"xiwangmu","pantheon_slug":"chinese","name":"서왕모","name_en":"Xiwangmu","epithet":"곤륜산의 여신","domains":["불사","신선"],"summary":"곤륜산에 살며 먹으면 늙지 않는 복숭아를 기르는, 도교 신선들의 여왕입니다.","description":["「산해경」의 서왕모는 표범 꼬리와 호랑이 이빨을 가진 무서운 모습이었지만, 시간이 지나며 아름다운 여신으로 바뀌었습니다.","도교에서는 곤륜산의 연못 요지 곁에 살며 불로장생의 복숭아 반도가 열리면 잔치를 연다고 여겨, 장수를 비는 그림의 주제가 되었습니다."],"sort_order":3},{"slug":"change","pantheon_slug":"chinese","name":"항아","name_en":"Chang'e","epithet":"달의 여신","domains":["달"],"summary":"불사의 약을 먹고 달로 올라가 월궁에 살게 된 여신으로, 상아라고도 부릅니다.","description":["항아는 활의 명수 예의 아내로, 예가 서왕모에게 받은 불사의 약을 먹고 몸이 가벼워져 달로 날아갔다고 합니다.","한나라 문제의 이름 글자를 피해 ‘상아’로 바꿔 부르게 되었으며, 중국의 달 탐사선 이름도 여기서 따왔습니다."],"sort_order":4},{"slug":"cernunnos","pantheon_slug":"celtic","name":"케르눈노스","name_en":"Cernunnos","epithet":"뿔 달린 신","domains":["동물","풍요","숲"],"summary":"사슴뿔을 단 채 다리를 꼬고 앉은 모습으로 켈트 유물에 남은, 이름조차 확실하지 않은 신입니다.","description":["‘케르눈노스’라는 이름은 1세기 파리의 ‘뱃사공의 기둥’에 새겨진 글자에서 왔으며, 켈트 유물의 뿔 달린 신을 통틀어 이렇게 부릅니다.","덴마크에서 나온 군데스트루프 솥에는 사슴뿔을 단 신이 한 손에 목걸이(토크)를, 다른 손에 뱀을 쥐고 짐승들에 둘러싸여 앉아 있습니다."],"sort_order":1},{"slug":"cuchulainn","pantheon_slug":"celtic","name":"쿠 훌린","name_en":"Cú Chulainn","epithet":"얼스터의 영웅","domains":["영웅","전쟁"],"summary":"어린 나이에 홀로 얼스터를 지킨, 아일랜드 신화에서 가장 이름난 영웅입니다.","description":["본래 이름은 세탄타였지만, 대장장이 쿨란의 사나운 개를 죽인 뒤 그 개 대신 집을 지키겠다고 하여 ‘쿨란의 개’라는 뜻의 쿠 훌린이 되었습니다.","「쿨리의 소 약탈」에서 코노트의 군대가 쳐들어오자 홀로 여울을 지키며 적의 용사들과 차례로 싸웠습니다. 전쟁의 여신 모리안과 얽힌 이야기도 많습니다."],"sort_order":2},{"slug":"brigid","pantheon_slug":"celtic","name":"브리지트","name_en":"Brigid","epithet":"불과 시, 치유의 여신","domains":["불","시","치유","대장장이 기술"],"summary":"시인과 치유사, 대장장이를 돕는 여신으로, 같은 이름의 성녀 브리지다와 겹쳐 전해집니다.","description":["브리지트(브리드)는 다그다의 딸로 전하며, 봄의 시작을 알리는 임볼크 축제와 이어집니다.","아일랜드가 기독교로 바뀐 뒤에는 킬데어의 성녀 브리지다와 겹쳐졌고, 성녀의 축일도 임볼크와 같은 2월 1일입니다."],"sort_order":3},{"slug":"morrigan","pantheon_slug":"celtic","name":"모리안","name_en":"The Morrígan","epithet":"전쟁과 운명의 여신","domains":["전쟁","운명","예언"],"summary":"까마귀로 변해 전장을 날며 승패와 죽음을 예고하는 아일랜드의 여신입니다.","description":["모리안은 ‘위대한 여왕’ 또는 ‘공포의 여왕’이라는 뜻으로 풀이되며, 자매들과 함께 세 여신으로 이야기되기도 합니다.","쿠 훌린에게 사랑을 구했다가 거절당한 뒤 그를 방해했다고 전합니다. 쿠 훌린이 죽을 때 그의 어깨에 까마귀가 내려앉았는데, 이 까마귀를 모리안으로 보기도 합니다."],"sort_order":4},{"slug":"quetzalcoatl","pantheon_slug":"aztec","name":"케찰코아틀","name_en":"Quetzalcoatl","epithet":"깃털 달린 뱀","domains":["바람","지혜","문명"],"summary":"‘깃털 달린 뱀’이라는 이름의, 메소아메리카 전역에서 숭배된 바람과 지혜의 신입니다.","description":["깃털 달린 뱀의 모습은 테오티우아칸 시대부터 나타나며, 아즈텍에서는 바람의 신 에에카틀의 모습으로도 섬겨졌습니다.","저승에서 옛 인류의 뼈를 가져와 자신의 피를 뿌려 지금의 인류를 만들었다고 전하며, 형제이자 맞수인 테스카틀리포카와 함께 세상을 만들고 무너뜨렸습니다."],"sort_order":1},{"slug":"tezcatlipoca","pantheon_slug":"aztec","name":"테스카틀리포카","name_en":"Tezcatlipoca","epithet":"연기 나는 거울","domains":["밤","운명","권력","마법"],"summary":"흑요석 거울로 세상을 보는 밤과 운명의 신으로, 케찰코아틀의 맞수입니다.","description":["이름은 나와틀어로 ‘연기 나는 거울’이라는 뜻이며, 잃어버린 한쪽 발 자리에 흑요석 거울을 단 모습으로 그려집니다.","첫 번째 태양인 재규어의 시대를 다스렸다고 전하며, 툴라의 왕이던 케찰코아틀을 속여 나라를 떠나게 만든 이야기가 유명합니다."],"sort_order":2},{"slug":"huitzilopochtli","pantheon_slug":"aztec","name":"우이칠로포치틀리","name_en":"Huitzilopochtli","epithet":"태양과 전쟁의 신","domains":["태양","전쟁"],"summary":"멕시카(아즈텍) 사람들을 이끌어 테노치티틀란을 세우게 한 태양과 전쟁의 신입니다.","description":["이름은 ‘남쪽의 벌새’라는 뜻으로 풀이되며, 어머니 코아틀리쿠에를 해치려던 누이 코욜샤우키와 형제들을 불의 뱀 시우코아틀로 물리쳤다고 합니다.","틀랄록과 함께 테노치티틀란의 큰 신전(템플로 마요르) 꼭대기에 나란히 선 두 사당에 모셔졌습니다."],"sort_order":3},{"slug":"tlaloc","pantheon_slug":"aztec","name":"틀랄록","name_en":"Tlaloc","epithet":"비와 번개의 신","domains":["비","번개","농사"],"summary":"고글 같은 눈 테와 송곳니로 알아볼 수 있는, 비와 농사를 다스리는 신입니다.","description":["틀랄록은 메소아메리카에서 오래전부터 섬긴 비의 신으로, 비를 내려 농사를 살리기도 하고 홍수와 가뭄을 부르기도 했습니다.","세 번째 태양의 시대를 다스렸다고 전하며, 우이칠로포치틀리와 함께 템플로 마요르 꼭대기의 두 사당에 모셔졌습니다."],"sort_order":4}]$seed$::jsonb)
on conflict (slug) do nothing;
insert into public.exhibits (id, figure_slug, title, kind, date_label, holder, note, image)
select id, figure_slug, title, kind, date_label, holder, note, image from jsonb_populate_recordset(null::public.exhibits, $seed$[{"id":"zeus-otricoli","figure_slug":"zeus","title":"오트리콜리의 제우스","kind":"sculpture","date_label":"로마 시대 (그리스 원작의 모작)","holder":"바티칸 박물관 피오 클레멘티노관","note":null,"image":{"src":"/images/exhibits/zeus-otricoli.jpg","width":1051,"height":1600,"alt":"곱슬거리는 긴 머리와 풍성한 수염을 한 제우스의 대리석 두상","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Zeus_Otricoli_Pio-Clementino_Inv257.jpg"}}},{"id":"athena-giustiniani","figure_slug":"athena","title":"아테나 주스티니아니","kind":"sculpture","date_label":"로마 시대 (그리스 원작의 모작)","holder":"바티칸 박물관 브라초 누오보","note":null,"image":{"src":"/images/exhibits/athena-giustiniani.jpg","width":1006,"height":1600,"alt":"투구를 쓰고 긴 창을 든 채 서 있는 아테나의 대리석 전신상. 발치에 뱀이 감겨 있습니다.","credit":{"artist":"Daderot","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Athena_Giustiniani_-_Braccio_Nuovo,_Museo_Chiaramonti_-_Vatican_Museums_-_DSC00910.jpg"}}},{"id":"apollo-belvedere","figure_slug":"apollo","title":"벨베데레의 아폴론","kind":"sculpture","date_label":"2세기경 (로마 시대 모작)","holder":"바티칸 박물관 피오 클레멘티노관","note":null,"image":{"src":"/images/exhibits/apollo-belvedere.jpg","width":1067,"height":1600,"alt":"곱슬머리를 묶어 올리고 어깨에 망토를 걸친 아폴론 대리석상의 상반신","credit":{"artist":"Marie-Lan Nguyen","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","sourceUrl":"https://commons.wikimedia.org/wiki/File:Belvedere_Apollo_Pio-Clementino_Inv1015_n3.jpg"}}},{"id":"venus-de-milo","figure_slug":"aphrodite","title":"밀로의 비너스","kind":"sculpture","date_label":"기원전 2세기경","holder":"루브르 박물관","note":"밀로스섬에서 발견되었으며, 아프로디테를 표현한 것으로 봅니다.","image":{"src":"/images/exhibits/venus-de-milo.jpg","width":953,"height":1600,"alt":"두 팔이 없고 허리 아래를 천으로 두른 아프로디테의 대리석 상","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Venus_de_Milo_Louvre_Ma399_n4.jpg"}}},{"id":"artemision-bronze","figure_slug":"poseidon","title":"아르테미시온 청동상","kind":"sculpture","date_label":"기원전 460년경","holder":"아테네 국립고고학박물관","note":"손에 든 무기가 사라져 번개를 던지는 제우스인지, 삼지창을 던지는 포세이돈인지 의견이 갈립니다.","image":{"src":"/images/exhibits/artemision-bronze.jpg","width":1067,"height":1600,"alt":"두 팔을 넓게 벌리고 무언가를 던지려는 자세를 한 수염 난 남신 청동상의 상반신","credit":{"artist":"Gary Todd from Xinzheng, China","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Ancient_Greece_Bronze_statue_of_Zeus_or_Poseidon;_from_the_sea_near_Cape_Artemision,_Northern_Euboea;_c._460_BC.jpg"}}},{"id":"odin-wanderer","figure_slug":"odin","title":"방랑자 오딘","kind":"painting","date_label":"1886년","holder":null,"note":null,"image":{"src":"/images/exhibits/odin-wanderer.jpg","width":500,"height":733,"alt":"챙 넓은 모자를 눌러쓰고 긴 흰 수염을 늘어뜨린 노인 모습의 오딘이 지팡이를 쥔 흑백 그림","credit":{"artist":"Georg von Rosen","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Georg_von_Rosen_-_Oden_som_vandringsman,_1886_(Odin,_the_Wanderer).jpg"}}},{"id":"odin-sleipnir","figure_slug":"odin","title":"궁니르를 들고 슬레이프니르를 탄 오딘","kind":"print","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/odin-sleipnir.jpg","width":686,"height":934,"alt":"긴 수염의 오딘이 창 궁니르를 세워 들고 말 슬레이프니르를 탄 모습을 그린 흑백 선 그림","credit":{"artist":"Lorenz Frølich","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Odin_holding_Gungnir_atop_Sleipnir_by_Fr%C3%B8lich.jpg"}}},{"id":"fenrir-odin","figure_slug":"odin","title":"펜리르와 오딘","kind":"print","date_label":"19세기","holder":null,"note":"라그나로크에서 오딘이 늑대 펜리르와 맞서는 장면입니다.","image":{"src":"/images/exhibits/fenrir-odin.jpg","width":1048,"height":627,"alt":"입을 크게 벌린 늑대 펜리르를 향해 창을 들고 말을 달리는 오딘을 덩굴무늬 테두리 안에 그린 흑백 삽화","credit":{"artist":"Lorenz Frølich","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Fenrir_and_Odin_by_Fr%C3%B8lich.jpg"}}},{"id":"thor-jotnar","figure_slug":"thor","title":"거인과 싸우는 토르","kind":"painting","date_label":"1872년","holder":"스웨덴 국립미술관","note":null,"image":{"src":"/images/exhibits/thor-jotnar.jpg","width":1081,"height":1600,"alt":"염소가 끄는 수레 위에서 망치를 치켜든 토르가 번개 속에서 거인들과 싸우는 그림","credit":{"artist":"Mårten Eskil Winge","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Thor%27s_Battle_Against_the_J%C3%B6tnar_(1872)_by_M%C3%A5rten_Eskil_Winge.jpg"}}},{"id":"freyja-brisingamen","figure_slug":"freyja","title":"브리싱가멘을 돌려주는 헤임달","kind":"painting","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/freyja-brisingamen.jpg","width":1176,"height":1600,"alt":"왕좌에 앉은 프레이야에게 투구를 쓴 헤임달이 몸을 기울여 목걸이를 건네고, 뒤에서 시녀들이 지켜보는 그림","credit":{"artist":"Nils Jakob Blommér","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Nils_Jakob_Blomm%C3%A9r_-_Heimdall_returns_Brisingamen_to_Freyja_-_Google_Art_Project.jpg"}}},{"id":"osiris-bronze","figure_slug":"osiris","title":"오시리스 청동 소상","kind":"sculpture","date_label":"고대 이집트","holder":"토리노 이집트 박물관","note":null,"image":{"src":"/images/exhibits/osiris-bronze.jpg","width":1102,"height":1600,"alt":"높은 관을 쓰고 두 팔을 가슴 앞에 모은 오시리스의 닳은 청동 소상. 옆에 크기를 재는 자가 놓여 있습니다.","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Osiris_statuette,_bronze_-_Museo_Egizio,_Turin_S_17631_p01.jpg"}}},{"id":"isis-horus","figure_slug":"isis","title":"호루스에게 젖을 먹이는 이시스","kind":"sculpture","date_label":"고대 이집트","holder":"메트로폴리탄 미술관","note":null,"image":{"src":"/images/exhibits/isis-horus.jpg","width":866,"height":1600,"alt":"소뿔과 해 원반 모양의 관을 쓰고 의자에 앉아 무릎 위의 아기 호루스에게 젖을 먹이는 이시스의 소상","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Isis_nursing_Horus_MET_17.190.1641_front.jpg"}}},{"id":"anubis-shrine","figure_slug":"anubis","title":"투탕카멘 무덤의 아누비스 신당","kind":"photograph","date_label":"기원전 14세기 (1920년대 발굴 당시 사진)","holder":"이집트 박물관 (카이로)","note":"하워드 카터의 발굴단 사진가 해리 버턴이 무덤 안에서 찍은 사진입니다.","image":{"src":"/images/exhibits/anubis-shrine.jpg","width":1180,"height":1466,"alt":"투탕카멘 무덤 보물실 입구를 찍은 흑백 사진. 앞쪽 상자 모양 신당 위에 아누비스 조각이 엎드려 있고 뒤로 유물이 쌓여 있습니다.","credit":{"artist":"Harry Burton","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Anubis-shrine_(cropped).jpg"}}},{"id":"weighing-heart","figure_slug":"anubis","title":"심장의 무게 달기 (후네페르의 「사자의 서」)","kind":"manuscript","date_label":"기원전 13세기경","holder":"대영박물관","note":"아누비스가 죽은 이의 심장을 진리의 깃털과 함께 저울에 달고, 토트가 결과를 적습니다. 오른쪽의 괴물 암무트는 심판을 통과하지 못한 심장을 삼킵니다.","image":{"src":"/images/exhibits/weighing-heart.jpg","width":1280,"height":659,"alt":"자칼 머리의 아누비스가 저울로 심장의 무게를 달고, 따오기 머리의 토트가 결과를 적는 장면을 그린 파피루스","credit":{"artist":"Photographed by the British Museum; original artist unknown","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:BD_Weighing_of_the_Heart.jpg"}}},{"id":"hero-lion","figure_slug":"gilgamesh","title":"사자를 제압하는 영웅","kind":"relief","date_label":"기원전 8세기","holder":"루브르 박물관","note":"아시리아 사르곤 2세의 궁전(두르샤루킨) 부조입니다. 길가메시로 보는 견해가 있지만 확실하지 않습니다.","image":{"src":"/images/exhibits/hero-lion.jpg","width":686,"height":1600,"alt":"수염을 기른 영웅이 한 팔로 사자를 끌어안고 다른 손에 무언가를 쥔 모습을 새긴 석조 부조","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Hero_lion_Dur-Sharrukin_Louvre_AO19862.jpg"}}},{"id":"queen-of-night","figure_slug":"ishtar","title":"밤의 여왕 (버니 부조)","kind":"relief","date_label":"기원전 1800~1750년경","holder":"대영박물관","note":"날개 달린 여신을 이슈타르(인안나)로 보는 견해와 그 언니 에레슈키갈로 보는 견해 등이 있습니다.","image":{"src":"/images/exhibits/queen-of-night.jpg","width":1203,"height":1600,"alt":"날개와 새의 발을 가진 여신이 두 마리 사자 위에 서서 양손에 고리와 막대를 들고, 양옆에 부엉이가 있는 점토 부조","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:British_Museum_Queen_of_the_Night.jpg"}}},{"id":"ishtar-gate-lion","figure_slug":"ishtar","title":"바빌론 행렬로의 사자","kind":"relief","date_label":"기원전 6세기","holder":"이스탄불 고고학 박물관","note":"사자는 이슈타르의 상징으로, 이슈타르 문으로 이어지는 행렬로의 벽을 장식했습니다.","image":{"src":"/images/exhibits/ishtar-gate-lion.jpg","width":1280,"height":854,"alt":"푸른 유약 벽돌 바탕 위로 걸어가는 사자를 새긴 벽돌 부조","credit":{"artist":"Marie-Lan Nguyen","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Lion_Ishtar_gate_IAM_inv88.143.jpg"}}},{"id":"marduk-seal","figure_slug":"marduk","title":"마르두크와 무슈후슈 (원통 인장 도판)","kind":"print","date_label":null,"holder":null,"note":"바빌로니아 원통 인장에 새긴 그림을 옮겨 그린 도판입니다.","image":{"src":"/images/exhibits/marduk-seal.jpg","width":778,"height":1274,"alt":"높은 관을 쓰고 장식이 많은 옷을 입은 마르두크와 그 발치의 용 모양 짐승 무슈후슈를 그린 선 그림","credit":{"artist":"Franz Heinrich Weißbach","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Marduk_and_pet.jpg"}}},{"id":"shiva-nataraja","figure_slug":"shiva","title":"나타라자 (춤추는 시바)","kind":"sculpture","date_label":null,"holder":"암스테르담 국립미술관 (라익스뮤지엄)","note":null,"image":{"src":"/images/exhibits/shiva-nataraja.jpg","width":1140,"height":1600,"alt":"불꽃 고리 안에서 네 팔을 펼치고 한 다리를 들어 춤추는 시바의 청동상","credit":{"artist":"Rijksmuseum","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Shiva_Nataraja,_AK-MAK-187.jpg"}}},{"id":"ganesha-rijks","figure_slug":"ganesha","title":"가네샤","kind":"sculpture","date_label":null,"holder":"암스테르담 국립미술관 (라익스뮤지엄)","note":null,"image":{"src":"/images/exhibits/ganesha-rijks.jpg","width":1132,"height":1600,"alt":"받침 위에 앉은 코끼리 머리의 가네샤를 새긴 석상","credit":{"artist":"Rijksmuseum","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Ganesha,_AK-MAK-237.jpg"}}},{"id":"vishnu-anantashayana","figure_slug":"vishnu","title":"아난타 위에 누운 비슈누","kind":"painting","date_label":"16~17세기","holder":"마탄체리 궁전 (인도 코치)","note":null,"image":{"src":"/images/exhibits/vishnu-anantashayana.jpg","width":1280,"height":1189,"alt":"머리가 여럿인 뱀 아난타 위에 누운 비슈누와 그 주위를 둘러싼 많은 신을 그린 궁전 벽화","credit":{"artist":"Rainer Halama","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Mattancherry_Palace-16-17th_Century_mural_paintings-Vishnu_Anantashayana-WUS09329.jpg"}}},{"id":"izanagi-izanami","figure_slug":"izanagi-izanami","title":"일본의 섬들을 만드는 이자나기와 이자나미","kind":"painting","date_label":"1880년대","holder":null,"note":null,"image":{"src":"/images/exhibits/izanagi-izanami.jpg","width":1280,"height":847,"alt":"구름 위에 선 이자나기와 이자나미. 한 신이 구슬 장식이 달린 창을 들고 있습니다.","credit":{"artist":"Kobayashi Eitaku","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Kobayashi_Eitaku_-_Izanami_and_Izanagi_creating_the_Japanese_Islands_alternate_version_HD.jpg"}}},{"id":"amaterasu-iwato","figure_slug":"amaterasu","title":"이와토 가구라의 기원","kind":"print","date_label":"1856년","holder":null,"note":"우타가와 구니사다(3대 도요쿠니)의 세 폭 목판화입니다.","image":{"src":"/images/exhibits/amaterasu-iwato.jpg","width":1280,"height":611,"alt":"세 폭으로 이어진 목판화. 가운데 위쪽에서 빛을 내며 동굴에서 나오는 아마테라스를 신들이 둘러싸고 있습니다.","credit":{"artist":"Toyokuni III","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Origin_of_Iwato_Kagura_Dance_Amaterasu_by_Toyokuni_III_(Kunisada)_1856.png"}}},{"id":"susanoo-orochi","figure_slug":"susanoo","title":"이즈모에서 야마타노오로치를 베는 스사노오","kind":"print","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/susanoo-orochi.jpg","width":1280,"height":633,"alt":"거친 파도 위에서 검을 휘두르는 스사노오와 그에게 달려드는 뱀 야마타노오로치를 그린 목판화","credit":{"artist":"Yoshitoshi","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Susanoo-no-Mikoto-slays-Yamata-no-Orochi-in-Izumo-By-Tsukioka-Yoshitoshi_repaired.png"}}},{"id":"raijin-hokusai","figure_slug":"raijin","title":"뇌신","kind":"painting","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/raijin-hokusai.jpg","width":590,"height":1600,"alt":"족자에 그린 그림. 소용돌이치는 먹구름 속에 붉은 몸의 뇌신이 있습니다.","credit":{"artist":"Katsushika Hokusai","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Katsushika_Hokusai_-_Thunder_God_-_Google_Art_Project.jpg"}}},{"id":"hera-barberini","figure_slug":"hera","title":"헤라 흉상","kind":"sculpture","date_label":"로마 시대 (그리스 원작의 모작)","holder":"바티칸 박물관","note":null,"image":{"src":"/images/exhibits/hera-barberini.jpg","width":1059,"height":1600,"alt":"물결치는 머리를 가운데로 가르고 머리띠를 두른 헤라의 대리석 흉상","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Hera_Barberini_Chiaramonti_Inv1210.jpg"}}},{"id":"artemis-versailles","figure_slug":"artemis","title":"베르사유의 디아나","kind":"sculpture","date_label":"1~2세기 (로마 시대 모작)","holder":"루브르 박물관","note":"로마에서는 아르테미스를 디아나라 불렀습니다.","image":{"src":"/images/exhibits/artemis-versailles.jpg","width":1200,"height":1600,"alt":"화살통에서 화살을 뽑으며 걸어가는 아르테미스와 그 곁에서 뛰어오르는 사슴을 새긴 대리석상","credit":{"artist":"Shonagon","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Diane_de_Versailles_-_Mus%C3%A9e_du_Louvre_AGER_Ma_589.jpg"}}},{"id":"hermes-ingenui","figure_slug":"hermes","title":"헤르메스 잉게누이","kind":"sculpture","date_label":"로마 시대 (그리스 원작의 모작)","holder":"바티칸 박물관","note":null,"image":{"src":"/images/exhibits/hermes-ingenui.jpg","width":731,"height":1600,"alt":"챙 있는 모자를 쓰고 어깨에 망토를 걸친 젊은 헤르메스가 지팡이를 든 대리석 전신상","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Hermes_Ingenui_Pio-Clementino_Inv544.jpg"}}},{"id":"hades-locri-pinax","figure_slug":"hades","title":"하데스와 페르세포네 (로크리의 봉헌판)","kind":"relief","date_label":"기원전 500~450년경","holder":"클리블랜드 미술관","note":"남이탈리아 로크리의 페르세포네 성소에서 나온 테라코타 봉헌판입니다.","image":{"src":"/images/exhibits/hades-locri-pinax.jpg","width":1200,"height":1600,"alt":"옥좌에 나란히 앉은 두 신과 옥좌 아래의 수탉을 새긴 테라코타 판. 한 신이 곡식 이삭과 꽃가지를 들고 있습니다.","credit":{"artist":"Daderot","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Pinax_with_Persephone_and_Hades_Enthroned,_500-450_BC,_Greek,_Locri_Epizephirii,_Mannella_district,_Sanctuary_of_Persephone,_terracotta_-_Cleveland_Museum_of_Art_-_DSC08242.JPG"}}},{"id":"baldr-eckersberg","figure_slug":"baldr","title":"발드르의 죽음","kind":"painting","date_label":"1817년","holder":null,"note":null,"image":{"src":"/images/exhibits/baldr-eckersberg.jpg","width":1280,"height":1014,"alt":"땅에 쓰러진 발드르를 둘러싸고 신들이 놀라고 슬퍼하는 그림","credit":{"artist":"Christoffer Wilhelm Eckersberg","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Baldr_dead_by_Eckersberg.jpg"}}},{"id":"heimdall-doepler","figure_slug":"heimdall","title":"무지개다리의 헤임달","kind":"print","date_label":"20세기 초","holder":null,"note":"에밀 되플러가 그린 북유럽 신화 삽화의 한 부분입니다.","image":{"src":"/images/exhibits/heimdall-doepler.jpg","width":752,"height":684,"alt":"투구를 쓴 헤임달이 무지개다리 곁에서 커다란 뿔피리를 부는 그림","credit":{"artist":"Emil Doepler","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Heimdall_an_der_Himmelsbr%C3%BCcke.jpg"}}},{"id":"ra-horakhty-stela","figure_slug":"ra","title":"라-호라크티 앞의 공양 석비","kind":"painting","date_label":"고대 이집트","holder":null,"note":null,"image":{"src":"/images/exhibits/ra-horakhty-stela.jpg","width":1280,"height":1525,"alt":"해 원반을 인 매 머리의 라-호라크티가 앉아 있고, 한 여인이 공물 상을 사이에 두고 마주 선 채색 석비","credit":{"artist":"Photograph by Oriental Institute, the University of Chicago; painter unknown","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Re-Horakhty_Stela.jpg"}}},{"id":"horus-edfu","figure_slug":"horus","title":"에드푸 신전의 호루스상","kind":"sculpture","date_label":"기원전 3~1세기 (프톨레마이오스 왕조)","holder":"에드푸 신전 (이집트)","note":null,"image":{"src":"/images/exhibits/horus-edfu.jpg","width":1280,"height":853,"alt":"신전 입구 앞에 서 있는 커다란 화강암 매 조각","credit":{"artist":"Vyacheslav Argenberg","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Temple_of_Edfu,_Statue_of_Horus,_Egypt.jpg"}}},{"id":"thoth-ibis","figure_slug":"thoth","title":"따오기 모습의 토트","kind":"sculpture","date_label":"고대 이집트","holder":"루브르 박물관","note":null,"image":{"src":"/images/exhibits/thoth-ibis.jpg","width":1280,"height":960,"alt":"검은 머리와 긴 굽은 부리, 흰 몸을 가진 따오기가 받침 위에 웅크린 조각","credit":{"artist":"Tangopaso","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Ibis_couch%C3%A9,_le_dieu_Thot_(Louvre,_E_17380).jpg"}}},{"id":"enki-adda-seal","figure_slug":"enki","title":"아다의 원통 인장","kind":"relief","date_label":"기원전 23세기경 (아카드 시대)","holder":"대영박물관","note":"어깨에서 물줄기와 물고기가 흘러나오는 신이 엔키(에아)입니다. 날개 달린 이슈타르와, 산 사이로 떠오르는 태양신 샤마시도 보입니다.","image":{"src":"/images/exhibits/enki-adda-seal.jpg","width":962,"height":611,"alt":"원통 인장을 굴려 찍은 자국. 어깨에서 물줄기가 흐르는 신, 날개 달린 여신, 산 사이에서 솟는 신이 나란히 새겨져 있습니다.","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Ea_(Babilonian)_-_EnKi_(Sumerian).jpg"}}},{"id":"tiamat-nimrud","figure_slug":"tiamat","title":"님루드 부조 도판 (번개를 든 신과 괴물)","kind":"print","date_label":"19세기 (원본 부조는 기원전 9세기)","holder":null,"note":"아시리아 님루드의 니누르타 신전 부조를 옮겨 그린 도판입니다. 마르두크와 티아마트의 싸움으로 흔히 소개되지만, 니누르타가 괴물을 물리치는 장면으로 보는 견해도 있습니다.","image":{"src":"/images/exhibits/tiamat-nimrud.jpg","width":1280,"height":944,"alt":"양손에 번개 다발을 든 날개 달린 신이 사자 머리에 새 발톱을 가진 괴물을 쫓는 선 그림","credit":{"artist":"editor Austen Henry Layard , drawing by L. Gruner","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Chaos_Monster_and_Sun_God.png"}}},{"id":"brahma-rijks","figure_slug":"brahma","title":"브라흐마","kind":"sculpture","date_label":null,"holder":"암스테르담 국립미술관 (라익스뮤지엄)","note":null,"image":{"src":"/images/exhibits/brahma-rijks.jpg","width":986,"height":1600,"alt":"여러 얼굴과 네 팔을 가진 브라흐마가 연꽃 받침 위에 선 청동상","credit":{"artist":"Rijksmuseum","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Brahma_en_Shiva_Brahma,_AK-MAK-249.jpg"}}},{"id":"krishna-govardhan","figure_slug":"krishna","title":"고바르다나산을 들어 올린 크리슈나","kind":"painting","date_label":"1590~1595년경 (무굴 제국)","holder":"메트로폴리탄 미술관","note":"무굴 궁정 화가 미스킨이 「하리밤샤」 사본에 그린 그림입니다.","image":{"src":"/images/exhibits/krishna-govardhan.jpg","width":1116,"height":1600,"alt":"푸른 피부의 크리슈나가 한 손으로 산을 들어 올리고, 그 아래로 마을 사람들과 소들이 비를 피한 그림","credit":{"artist":"Miskin","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Krishna_Holds_Up_Mount_Govardhan_to_Shelter_the_Villagers_of_Braj,_ca.1590%E2%80%9395,_The_Met.jpg"}}},{"id":"fujin-sotatsu","figure_slug":"fujin","title":"풍신뇌신도 (오른쪽 병풍, 후진)","kind":"painting","date_label":"17세기","holder":"겐닌지 (교토)","note":"다와라야 소타쓰의 두 폭 병풍 가운데 후진을 그린 오른쪽 폭입니다. 라이진은 왼쪽 폭에 있습니다.","image":{"src":"/images/exhibits/fujin-sotatsu.jpg","width":1280,"height":1136,"alt":"금박 바탕 위에서 바람 자루를 머리 위로 펼치고 구름을 타고 달리는 초록빛 몸의 후진","credit":{"artist":"Tawara Sōtatsu","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Tawaraya_S%C5%8Dtatsu_-_The_Gods_of_Wind_and_Thunder_(right_screen).jpg"}}},{"id":"inari-foxfires","figure_slug":"inari","title":"오지 팽나무 아래의 섣달그믐 여우불","kind":"print","date_label":"1857년","holder":null,"note":"우타가와 히로시게의 「명소 에도 백경」 가운데 한 장입니다.","image":{"src":"/images/exhibits/inari-foxfires.jpg","width":1049,"height":1600,"alt":"밤하늘 아래 큰 나무 곁에 여우들이 모여 있고, 여우마다 작은 불빛이 떠 있는 목판화","credit":{"artist":"Utagawa Hiroshige","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Hiroshige,_New_Year%27s_Eve_foxfires_at_the_changing_tree,_Oji,_1857.jpg"}}},{"id":"pangu","figure_slug":"pangu","title":"반고 (「삼재도회」)","kind":"print","date_label":"1609년","holder":null,"note":"명나라의 백과사전 「삼재도회」에 실린 삽화입니다.","image":{"src":"/images/exhibits/pangu.jpg","width":1014,"height":1546,"alt":"머리에 작은 뿔이 돋고 온몸이 긴 털로 덮인 반고를 그린 흑백 목판 삽화","credit":{"artist":"Wang Qi","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Pangu.jpg"}}},{"id":"fuxi-nuwa","figure_slug":"nuwa","title":"복희와 여와","kind":"painting","date_label":null,"holder":null,"note":"두 신의 윗몸은 사람이고 아랫몸은 서로 꼬인 뱀입니다. 둘레에 해와 별자리가 그려져 있습니다.","image":{"src":"/images/exhibits/fuxi-nuwa.jpg","width":766,"height":1600,"alt":"윗몸은 사람, 아랫몸은 서로 꼬인 뱀인 복희와 여와가 자와 컴퍼스를 들고, 위아래에 해와 달, 둘레에 별이 그려진 그림","credit":{"artist":"anonymous","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Anonymous-Fuxi_and_N%C3%BCwa.jpg"}}},{"id":"xiwangmu-kano","figure_slug":"xiwangmu","title":"서왕모","kind":"painting","date_label":"19세기","holder":"메트로폴리탄 미술관","note":"일본 가노파 화가 가노 오사노부가 그린 족자입니다.","image":{"src":"/images/exhibits/xiwangmu-kano.jpg","width":1200,"height":1600,"alt":"족자 그림. 소나무 가지 아래 흰 옷을 입은 서왕모가 서 있습니다.","credit":{"artist":"Kano Osanobu","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:%E8%A5%BF%E7%8E%8B%E6%AF%8D%E5%9B%B3-Queen_Mother_of_the_West_MET_DP333861.jpg"}}},{"id":"change-moon","figure_slug":"change","title":"달의 여신 항아","kind":"painting","date_label":null,"holder":null,"note":"명나라 화가 당인의 그림을 따라 그린 작품입니다.","image":{"src":"/images/exhibits/change-moon.jpg","width":841,"height":1600,"alt":"긴 소매 옷을 입은 항아가 서 있고 위쪽에 글이 적힌 세로 족자","credit":{"artist":"Unknown artist, after Tang Yin","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:The_Moon_Goddess_Chang_E_-_Unidentified_artist,_after_Tang_Yin.jpg"}}},{"id":"cernunnos-gundestrup","figure_slug":"cernunnos","title":"군데스트루프 솥의 뿔 달린 신","kind":"relief","date_label":"기원전 2~1세기","holder":"덴마크 국립박물관","note":null,"image":{"src":"/images/exhibits/cernunnos-gundestrup.jpg","width":1280,"height":871,"alt":"사슴뿔을 단 신이 다리를 꼬고 앉아 한 손에 목걸이, 다른 손에 뱀을 쥐고 사슴과 짐승들에 둘러싸인 은 부조","credit":{"artist":"Nationalmuseet, Roberto Fortuna og Kira Ursem","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Gundestrupkedlen-_00054_(cropped).jpg"}}},{"id":"cuchulainn-leyendecker","figure_slug":"cuchulainn","title":"전투하는 쿠 훌린","kind":"painting","date_label":"1911년","holder":null,"note":null,"image":{"src":"/images/exhibits/cuchulainn-leyendecker.jpg","width":1079,"height":1553,"alt":"투구를 쓴 쿠 훌린이 전차 위에서 창을 치켜들고 돌진하는 그림","credit":{"artist":"Joseph Christian Leyendecker","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Cuchulain_in_Battle.jpg"}}},{"id":"brigid-duncan","figure_slug":"brigid","title":"성녀 브리지다","kind":"painting","date_label":"1913년","holder":"스코틀랜드 국립미술관","note":"천사들이 성녀 브리지다를 바다 건너 베들레헴으로 데려간다는 스코틀랜드 헤브리디스의 전설을 그렸습니다.","image":{"src":"/images/exhibits/brigid-duncan.jpg","width":1280,"height":1081,"alt":"날개 달린 두 천사가 흰 옷의 브리지다를 안고 바다 위를 날아가는 그림","credit":{"artist":"John Duncan","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:John_Duncan_(1913)_Saint_Bride.jpg"}}},{"id":"morrigan","figure_slug":"morrigan","title":"까마귀 (「전투하는 쿠 훌린」 부분)","kind":"painting","date_label":"1911년","holder":null,"note":"라이엔데커의 「전투하는 쿠 훌린」에서 까마귀 부분을 잘라 낸 이미지입니다. 전장을 나는 까마귀는 모리안의 모습으로 여겨집니다.","image":{"src":"/images/exhibits/morrigan.jpg","width":500,"height":648,"alt":"붉은 하늘을 배경으로 창끝 곁을 날아가는 검은 까마귀","credit":{"artist":"Joseph Christian Leyendecker","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Morrigan.jpg"}}},{"id":"quetzalcoatl-borbonicus","figure_slug":"quetzalcoatl","title":"케찰코아틀과 테스카틀리포카 (보르보니쿠스 코덱스)","kind":"manuscript","date_label":"16세기 초","holder":"프랑스 국회도서관","note":null,"image":{"src":"/images/exhibits/quetzalcoatl-borbonicus.jpg","width":550,"height":496,"alt":"화려한 깃털과 장신구로 꾸민 두 신이 마주 보고 선 그림 문서","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Quetzalcoatl_and_Tezcatlipoca.jpg"}}},{"id":"tezcatlipoca-borgia","figure_slug":"tezcatlipoca","title":"보르자 코덱스 17쪽","kind":"manuscript","date_label":"15세기 말~16세기 초","holder":"바티칸 도서관","note":"가운데에 크게 그려진 신이 테스카틀리포카입니다.","image":{"src":"/images/exhibits/tezcatlipoca-borgia.jpg","width":1280,"height":1280,"alt":"가운데 화려한 장식의 신이 크게 그려지고, 둘레에 작은 그림 기호들이 빼곡한 그림 문서 한 쪽","credit":{"artist":"Unknown author","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Codex_Borgia_page_17.jpg"}}},{"id":"huitzilopochtli-wdl","figure_slug":"huitzilopochtli","title":"우이칠로포치틀리 (토바르 코덱스)","kind":"manuscript","date_label":"16세기 후반","holder":"존 카터 브라운 도서관","note":"후안 데 토바르가 정리한 아즈텍 역사 사본의 그림입니다.","image":{"src":"/images/exhibits/huitzilopochtli-wdl.jpg","width":1280,"height":963,"alt":"새 머리 투구를 쓴 우이칠로포치틀리가 방패와 뱀 모양 무기를 들고 앉은 그림","credit":{"artist":"Tovar, Juan de, circa 1546-circa 1626","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Huitzilopochtli,_the_Principal_Aztec_God_WDL6725.png"}}},{"id":"tlaloc-borgia","figure_slug":"tlaloc","title":"틀랄록 (보르자 코덱스)","kind":"manuscript","date_label":"15세기 말~16세기 초","holder":"바티칸 도서관","note":null,"image":{"src":"/images/exhibits/tlaloc-borgia.jpg","width":1280,"height":601,"alt":"고글 같은 눈 테와 송곳니를 가진 틀랄록 여럿이 가로로 늘어선 그림 문서","credit":{"artist":"Unknown author","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Tlaloc_Codex_Borgia.jpg"}}}]$seed$::jsonb)
